package com.skyreserve.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="bookings",uniqueConstraints=@UniqueConstraint(columnNames={"flightId","seat"})) public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String bookingCode; Long flightId; String passenger,email,seat,status,paymentStatus; double amount; LocalDateTime bookedAt; public Long getId(){return id;} public String getBookingCode(){return bookingCode;} public void setBookingCode(String v){bookingCode=v;} public Long getFlightId(){return flightId;} public void setFlightId(Long v){flightId=v;} public String getPassenger(){return passenger;} public void setPassenger(String v){passenger=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getSeat(){return seat;} public void setSeat(String v){seat=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public double getAmount(){return amount;} public void setAmount(double v){amount=v;} public String getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(String v){paymentStatus=v;} public LocalDateTime getBookedAt(){return bookedAt;} public void setBookedAt(LocalDateTime v){bookedAt=v;} }
